484→    function normalizeZip(raw) {
485→      var z = raw.trim().toUpperCase();
486→      z = z.replace(/\s+/g, '');        // collapse all spaces (UK: SW1A 2AA → SW1A2AA)
487→      z = z.replace(/-\d{4}$/, '');     // strip US ZIP+4 suffix (90210-1234 → 90210)
488→      return z;
489→    }
