495→      if (loading) {
496→        btn.classList.add('zcc-btn--loading');
497→        if (iconEl) iconEl.innerHTML = ICONS.spinner;
498→        if (labelEl) labelEl.style.display = 'none';
499→      } else {
500→        btn.classList.remove('zcc-btn--loading');
501→        if (iconEl) iconEl.innerHTML = ICONS.search;
502→        if (labelEl) { labelEl.style.display = ''; labelEl.textContent = cfg.buttonText; }
503→      }
504→    }
