513→
514→      fetch(
515→        API_BASE + "/api/zip-check?shop=" + encodeURIComponent(SHOP) +
516→          "&zip=" + encodeURIComponent(zip)
517→      )
518→        .then(function (r) {
519→          if (!r.ok) {
520→            // Non-2xx: try to parse JSON error body, fall back to status text
521→            return r.json().catch(function() {
522→              return { error: 'Server error (' + r.status + ')' };
523→            });
524→          }
525→          return r.json();
526→        })
527→        .then(function (data) {
528→          setBtnLoading(false);
529→
530→          // If the API returned an error object (no allowed field), treat as a
